// AM pick_tickets -> canonical PickTicket[]. Falls back to a realistic
// sample if AM has none yet (nothing released/picked in the test company).
const num = (v) => (v == null || v === '' ? null : Number(v));
const resp = $input.first().json.response || [];
const records = resp.length ? resp : [{
  pick_ticket_id: 'SAMPLE-3000', order_id: null, customer_id: '1', customer_po: 'PO6979505951736416',
  warehouse_id: '1', date: new Date().toISOString().slice(0,10), date_due: null,
  ship_to_name: 'Best Store Ever', address_1: '111 Main Street', address_2: null,
  city: 'West Palm Beach', state: 'FL', postal_code: '33405', country: 'USA',
  ship_via: null, tracking_number: null, qty: '45', amount: '899.55',
  pick_ticket_items: [ { product_id: '4', sku_id: '4', attr_2: 'BLK', size: 'M100', style_number: 'JEAN1', description: 'Classic Denim Jean', qty: '45', unit_price: '19.99', amount: '899.55', is_taxable: '0' } ]
}];
const isSample = resp.length === 0;

return records.map((record) => ({ json: { isSample, pickTicket: {
  pickTicketId: record.pick_ticket_id, orderId: record.order_id || null, customerId: record.customer_id,
  customerPo: record.customer_po || null, warehouseId: record.warehouse_id || null,
  date: record.date ?? null, dateDue: record.date_due || null,
  shipTo: { name: record.ship_to_name || null, address1: record.address_1 || null, address2: record.address_2 || null, city: record.city || null, state: record.state || null, zip: record.postal_code || null, country: record.country || null },
  shipVia: record.ship_via || null, trackingNumber: record.tracking_number || null,
  qty: num(record.qty), amount: num(record.amount),
  lines: (record.pick_ticket_items || []).map((item) => ({ productId: item.product_id, skuId: item.sku_id, color: item.attr_2 || null, size: item.size || null, styleNumber: item.style_number || null, description: item.description || null, qty: num(item.qty), unitPrice: num(item.unit_price), amount: num(item.amount), isTaxable: item.is_taxable === '1' })),
} } }));

// AM purchase_orders -> canonical PurchaseOrder[]. Falls back to a
// realistic sample if AM has none yet (no vendor POs entered).
const num = (v) => (v == null || v === '' ? null : Number(v));
const resp = $input.first().json.response || [];
const records = resp.length ? resp : [{
  purchase_order_id: 'SAMPLE-4000', vendor_id: '2', warehouse_id: '1',
  date: new Date().toISOString().slice(0,10), date_start: null, date_due: null,
  shipping_address_override: '0', address_1: '111 Main Street', address_2: null, city: 'West Palm Beach', state: 'FL', postal_code: '33405', country: 'USA',
  ship_via: null, tracking_number: null, qty: '100', qty_received: '0', qty_open: '100', amount: '2500.00',
  purchase_order_items: [ { product_id: '4', sku_id: '4', attr_2: 'BLK', size: 'M100', style_number: 'JEAN1', description: 'Classic Denim Jean', qty: '100', qty_open: '100', qty_received: '0', unit_cost: '9.695', amount: '969.50' } ]
}];
const isSample = resp.length === 0;

return records.map((record) => ({ json: { isSample, purchaseOrder: {
  purchaseOrderId: record.purchase_order_id, vendorId: record.vendor_id, warehouseId: record.warehouse_id || null,
  date: record.date ?? null, dateStart: record.date_start || null, dateDue: record.date_due || null,
  shipTo: { address1: record.shipping_address_override === '1' ? record.shipping_address_1 : record.address_1, address2: record.shipping_address_override === '1' ? record.shipping_address_2 : record.address_2, city: record.shipping_address_override === '1' ? record.shipping_city : record.city, state: record.shipping_address_override === '1' ? record.shipping_state : record.state, zip: record.shipping_address_override === '1' ? record.shipping_postal_code : record.postal_code, country: record.shipping_address_override === '1' ? record.shipping_country : record.country },
  shipVia: record.ship_via || null, trackingNumber: record.tracking_number || null,
  qty: num(record.qty), qtyReceived: num(record.qty_received), qtyOpen: num(record.qty_open), amount: num(record.amount),
  lines: (record.purchase_order_items || []).map((item) => ({ productId: item.product_id, skuId: item.sku_id, color: item.attr_2 || null, size: item.size || null, styleNumber: item.style_number || null, description: item.description || null, qty: num(item.qty), qtyOpen: num(item.qty_open), qtyReceived: num(item.qty_received), unitCost: num(item.unit_cost), amount: num(item.amount) })),
} } }));

// Combine AM products (header) + inventory (per-SKU UPC/color/size) into
// canonical Item[] -- one per product, with its matching SKUs attached.
const num = (v) => (v == null || v === '' ? null : Number(v));
const products = $('Get AM Products').first().json.response || [];
const skus = $('Get AM Inventory (SKUs)').first().json.response || [];
const skusByProduct = {};
for (const sku of skus) {
  (skusByProduct[sku.product_id] ??= []).push(sku);
}

return products.map((product) => ({ json: { item: {
  productId: product.product_id, styleNumber: product.style_number, description: product.description ?? null,
  category: product.category || null, group: product.group || null, origin: product.origin || null, content: product.content || null,
  weight: num(product.weight), boxSize: product.box_size || null, isTaxable: product.is_taxable === '1',
  cost: num(product.cost), price: num(product.price),
  skus: (skusByProduct[product.product_id] || []).map((sku) => ({
    skuId: sku.sku_id, color: sku.attr_2 || null, colorName: sku.attr_2_name || null, size: sku.size || null,
    upc: sku.upc_display || sku.upc_11 || null, price: num(sku.price), cost: num(sku.cost), weight: num(sku.weight), active: sku.active === '1',
  })),
} } }));
